<?php

namespace Modules\EnterpriseFramework\Services\Print;

class EnterprisePrintLayoutService
{
    public function layout(array $context = []): array
    {
        return [
            'paper' => $context['paper'] ?? 'A4',
            'orientation' => $context['orientation'] ?? 'portrait',
            'show_company_header' => true,
            'show_branch' => true,
            'show_date_range' => true,
            'show_generated_metadata' => true,
            'footer_text' => $context['footer_text'] ?? 'Generated by Enterprise Framework',
        ];
    }
}
